globalThis.CIF_POSTS = POSTS;



const PAGE = 50;
const MODE = document.body.dataset.mode || "merged";
const state = {
  q: "",
  hidden: new Set(),
  density: "pair",
  range: "14",
  customFrom: "",
  customTo: "",
  shown: PAGE
};

function esc(s) {
  return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}
function linkify(text) {
  const spaced = text
    .replace(/([!?])([A-Za-z])/g, "$1 $2")
    .replace(/([^\s])(https?:\/\/)/g, "$1 $2");
  return esc(spaced).replace(/(https?:\/\/[^\s<&]+)/g, (url) => {
    const glued = url.match(/^(https?:\/\/.*\d)([A-Z][a-z].*)$/);
    const href = glued ? glued[1] : url;
    const rest = glued ? glued[2] : "";
    return '<a href="' + href + '" target="_blank" rel="noopener">' + href + "</a>" + rest;
  });
}
function dayLabel(iso) {
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d)).toLocaleDateString("en-US", {
    weekday: "long", month: "long", day: "numeric", timeZone: "UTC"
  });
}
function initials(post) {
  if (post.handle === "realDonaldTrump") return "DT";
  if (post.handle === "WhiteHouse") return "WH";
  return "RR";
}
function accountColor(post) {
  if (post.platform !== "X") return "var(--truth)";
  if (post.handle === "RapidResponse47") return "var(--x-rapid)";
  return "var(--x-whitehouse)";
}
function platformColor(post) {
  return post.platform === "X" ? "var(--plat-x)" : "var(--plat-truth)";
}
function num(n) {
  n = Number(n) || 0;
  if (n < 1000) return n.toLocaleString("en-US");
  const scaled = n >= 1000000 ? n / 1000000 : n / 1000;
  const rounded = Math.round(scaled * 10) / 10;
  const text = Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(1);
  return text + (n >= 1000000 ? "m" : "k");
}
function asOf(post) {
  if (!post.collectedAt) return "";
  const dt = new Date(post.collectedAt);
  if (Number.isNaN(dt.getTime())) return "";
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/Los_Angeles",
    hour: "numeric", minute: "numeric", hour12: true,
    month: "numeric", day: "numeric", year: "2-digit"
  }).formatToParts(dt);
  const get = (type) => parts.find((part) => part.type === type).value;
  const minute = get("minute");
  const ampm = get("dayPeriod").toLowerCase().replace(/\./g, "");
  const clock = minute === "00" ? get("hour") + ampm : get("hour") + ":" + minute + ampm;
  return "as of " + clock + " " + get("month") + "/" + get("day") + "/" + get("year");
}
function accountLabel(post) {
  return post.account;
}
function accountIcon(post) {
  const file = post.handle === "WhiteHouse" ? "icons/whitehouse.png"
    : post.handle === "RapidResponse47" ? "icons/rapid.png"
    : "icons/truth.png";
  return '<img class="acct-icon" src="' + file + '" alt="">';
}
function countsPhrase(post) {
  const pulled = asOf(post);
  return num(post.likes) + " likes · " + num(post.replies) + " replies · " + num(post.boosts) + " " + esc(post.boostLabel)
    + (pulled ? " · " + pulled : "");
}
function todayET() {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York",
    year: "numeric", month: "2-digit", day: "2-digit"
  }).formatToParts(new Date());
  const get = (type) => parts.find((part) => part.type === type).value;
  return get("year") + "-" + get("month") + "-" + get("day");
}
function shiftDays(iso, delta) {
  const [y, m, d] = iso.split("-").map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  dt.setUTCDate(dt.getUTCDate() + delta);
  const mm = String(dt.getUTCMonth() + 1).padStart(2, "0");
  const dd = String(dt.getUTCDate()).padStart(2, "0");
  return dt.getUTCFullYear() + "-" + mm + "-" + dd;
}
function presetRange(days) {
  const to = todayET();
  return { from: shiftDays(to, -days), to: to };
}
function activeRange() {
  if (state.range === "custom") return { from: state.customFrom, to: state.customTo };
  return presetRange(Number(state.range));
}
function rangeInvalid(range) {
  if (!range.from || !range.to) return true;
  return range.from > range.to;
}
function prettyDay(iso, withYear) {
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d)).toLocaleDateString("en-US", {
    month: "short", day: "numeric", year: withYear ? "numeric" : undefined, timeZone: "UTC"
  });
}
function rangeText(range) {
  const withYear = range.from.slice(0, 4) !== range.to.slice(0, 4);
  return prettyDay(range.from, withYear) + " \u2013 " + prettyDay(range.to, withYear);
}
function platformOk(post) {
  return !state.hidden.has(post.handle);
}
function queryOk(post) {
  const q = state.q.trim().toLowerCase();
  if (!q) return true;
  const hay = [post.summary, (post.topics || []).join(" "), post.text, post.account, post.handle, post.platform, post.repostOf, post.time, post.hour, post.day, dayLabel(post.day)].join("\n").toLowerCase();
  return q.split(/\s+/).every((word) => hay.includes(word));
}
function matching() {
  const range = activeRange();
  if (rangeInvalid(range)) return [];
  return POSTS.filter((post) => post.day >= range.from && post.day <= range.to && platformOk(post) && queryOk(post) && extraOk(post));
}
function extraOk(post) {
  const extra = globalThis.CIF_FILTER;
  return typeof extra !== "function" || extra(post);
}
function condensedWho(post) {
  const color = accountColor(post);
  return '<span class="who"><span class="avatar" style="background:' + color + '">' + initials(post) + "</span><span>"
    + '<span class="name">' + esc(post.account) + "</span>"
    + '<span class="handle">'
    + (post.repostOf ? '<span class="plat" style="color:' + color + '">Repost · </span>' : "")
    + "@" + esc(post.handle) + " · " + esc(post.time) + " · " + esc(dayLabel(post.day)) + "</span>"
    + "</span></span>";
}
function whoBlock(post) {
  const color = accountColor(post);
  return '<div class="who">' + accountIcon(post) + "<div>"
    + '<div class="name">' + esc(accountLabel(post)) + "</div>"
    + '<div class="handle">'
    + (post.repostOf ? '<span class="plat" style="color:' + color + '">Repost · </span>' : "")
    + "@" + esc(post.handle) + " · " + esc(post.time) + " · " + esc(dayLabel(post.day)) + "</div>"
    + "</div></div>";
}
function countsLine(post) {
  return '<p class="counts">' + countsPhrase(post) + "</p>";
}
function openLink(post) {
  const label = post.platform === "X" ? "Open on X" : "Open on Truth Social";
  return '<a class="original" href="' + esc(post.url) + '" target="_blank" rel="noopener">' + label + "</a>";
}
function postBody(post) {
  const pics = post.images.map((src) => '<img src="' + esc(src) + '" alt="" loading="lazy" decoding="async">').join("");
  const picBlock = pics ? '<div class="pics' + (post.images.length > 1 ? " multi" : "") + '">' + pics + "</div>" : "";
  const body = post.text.trim() ? '<p class="text">' + linkify(post.text) + "</p>" : "";
  const noText = post.text.trim() ? "" : '<p class="no-text">(no text)</p>';
  return body + picBlock + noText;
}
function topicText(post) {
  return (post.topics || []).join(" · ");
}
function shortPlat(post) {
  return post.platform === "X" ? "X" : "Truth";
}
function opened(post) {
  return '<div class="opened soc">'
    + postBody(post) + countsLine(post) + openLink(post) + "</div>";
}
function postTitle(post) {
  return post.summary || "No title yet";
}
function card(post) {
  if (mode === "condensed" && state.density === "line") return lineCard(post);
  if (mode === "condensed" && state.density === "pair") return pairCard(post);
  return '<article class="post" id="p-' + esc(post.id) + '" style="--bar:' + platformColor(post) + '">'
    + whoBlock(post)
    + postBody(post)
    + countsLine(post)
    + openLink(post)
    + "</article>";
}
function lineCard(post) {
  const thumb = post.images.length
    ? '<img class="tick-thumb" alt="" src="' + esc(post.images[0]) + '" loading="lazy" decoding="async" onerror="this.remove()">'
    : "";
  return '<article class="rowline" id="p-' + esc(post.id) + '" style="--bar:' + platformColor(post) + '">'
    + '<details data-pid="' + esc(post.id) + '"><summary>'
    + '<span class="tick-time">' + esc(post.time) + "</span>"
    + '<span class="who-name">' + esc(accountLabel(post)) + "</span>"
    + '<span class="tick-line">' + esc(postTitle(post)) + "</span>"
    + thumb
    + "</summary>" + opened(post) + "</details></article>";
}
function pairCard(post) {
  const topic = topicText(post);
  const meta = '<span class="who-name">' + esc(accountLabel(post)) + "</span>"
    + (post.repostOf ? " · Repost" : "")
    + ' <span class="pair-counts">· ' + countsPhrase(post) + "</span>"
    + (topic ? ' · <span class="kw">' + esc(topic) + "</span>" : "");
  return '<article class="rowpair" id="p-' + esc(post.id) + '" style="--bar:' + platformColor(post) + '">'
    + '<details data-pid="' + esc(post.id) + '"><summary>'
    + '<span class="tick-time">' + esc(post.time) + "</span>"
    + '<span class="icon-cell">' + accountIcon(post) + "</span>"
    + '<span class="pair-body">'
    + '<span class="pair-title">' + esc(postTitle(post)) + "</span>"
    + '<span class="pair-meta">' + meta + "</span>"
    + "</span></summary>" + opened(post) + "</details></article>";
}
function groupRow(post) {
  const topic = topicText(post);
  return '<details class="run-row" data-pid="' + esc(post.id) + '"><summary>'
    + '<span class="tick-time">' + esc(post.time) + "</span>"
    + (post.repostOf ? '<span class="tick-flag">Repost</span>' : "")
    + '<span class="tick-line">' + esc(postTitle(post)) + "</span>"
    + (topic ? '<span class="tick-topic">' + esc(topic) + "</span>" : "")
    + '<span class="tick-likes">' + num(post.likes) + " likes</span>"
    + "</summary>" + opened(post) + "</details>";
}
function spineCard(post) {
  return '<article class="spine-card" id="p-' + esc(post.id) + '" style="--bar:' + platformColor(post) + '">'
    + '<details name="cif-timeline" data-pid="' + esc(post.id) + '"><summary>'
    + '<span class="icon-cell">' + accountIcon(post) + "</span>"
    + '<span class="pair-body">'
    + '<span class="pair-title">' + esc(postTitle(post)) + "</span>"
    + "</span></summary>" + opened(post) + "</details></article>";
}
function renderSpine(posts) {
  const days = [];
  const byDay = new Map();
  posts.forEach((post) => {
    if (!byDay.has(post.day)) {
      byDay.set(post.day, []);
      days.push(post.day);
    }
    byDay.get(post.day).push(post);
  });
  let html = '<div class="spine" role="region" aria-label="Timeline">';
  days.forEach((day) => {
    html += '<section class="spine-day">'
      + '<h2 class="spine-day-label">' + esc(dayLabel(day)) + "</h2>"
      + '<div class="spine-cols" aria-hidden="true">'
      + '<div class="col-x">X (Twitter)</div><div class="col-time" aria-hidden="true"></div><div class="col-truth">Truth Social</div>'
      + "</div>"
      + '<ol class="spine-list">';
    byDay.get(day).forEach((post) => {
      const side = post.platform === "X" ? "left" : "right";
      const cardHtml = spineCard(post);
      html += '<li class="spine-item ' + side + '" style="--bar:' + platformColor(post) + '">'
        + '<div class="slot left">' + (side === "left" ? cardHtml : "") + "</div>"
        + '<div class="hub">'
        + '<span class="spine-dot" aria-hidden="true"></span>'
        + '<time class="spine-time" datetime="' + esc(post.sort) + '">' + esc(post.time) + "</time>"
        + "</div>"
        + '<div class="slot right">' + (side === "right" ? cardHtml : "") + "</div>"
        + "</li>";
    });
    html += "</ol></section>";
  });
  return html + "</div>";
}
function bindSpineAccordion(root) {
  root.querySelectorAll(".spine-card details").forEach((panel) => {
    panel.addEventListener("toggle", () => {
      if (!panel.open) return;
      const row = panel.closest(".spine-item");
      if (!row) return;
      requestAnimationFrame(() => {
        row.scrollIntoView({ block: "nearest", behavior: "smooth" });
      });
    });
  });
}
function dateRule(day) {
  return '<div class="date-rule"><span>' + esc(dayLabel(day)) + "</span></div>";
}
function renderCondensed(posts) {
  let html = "";
  let lastDay = "";
  posts.forEach((post) => {
    if (post.day !== lastDay) {
      html += dateRule(post.day);
      lastDay = post.day;
    }
    html += card(post);
  });
  return html;
}
function renderMerged(posts) {
  let html = "";
  let lastKey = "";
  posts.forEach((post) => {
    const key = post.day + "|" + post.hour;
    if (key !== lastKey) {
      html += '<h2 class="hour">' + esc(dayLabel(post.day)) + " · " + esc(post.hour) + "</h2>";
      lastKey = key;
    }
    html += card(post);
  });
  return html;
}
function renderGrouped(posts) {
  let html = "";
  let lastDay = "";
  let buffer = [];
  function flush() {
    if (!buffer.length) return;
    if (buffer.length === 1) html += lineCard(buffer[0]);
    else {
      const post = buffer[0];
      html += '<div class="run" style="--bar:' + platformColor(post) + '">'
        + '<div class="run-head">' + accountIcon(post) + '<span class="who-name">' + esc(accountLabel(post)) + "</span> · " + buffer.length + " posts</div>";
      buffer.forEach((item) => { html += groupRow(item); });
      html += "</div>";
    }
    buffer = [];
  }
  posts.forEach((post) => {
    if (post.day !== lastDay) {
      flush();
      html += dateRule(post.day);
      lastDay = post.day;
    }
    if (buffer.length && buffer[0].handle !== post.handle) flush();
    buffer.push(post);
  });
  flush();
  return html;
}
function emptyMessage(range) {
  if (rangeInvalid(range)) return "The start date is after the end date.";
  if (state.hidden.size === 3) return "Every account is switched off.";
  const q = state.q.trim();
  const withYear = range.from && range.to && range.from.slice(0, 4) !== range.to.slice(0, 4);
  const span = range.from && range.to
    ? prettyDay(range.from, withYear) + " to " + prettyDay(range.to, withYear)
    : "this range";
  if (q) return "No posts match \u201c" + esc(q) + "\u201d from " + span + ".";
  return "No posts from " + span + ".";
}
function tallyText(painted, total) {
  const n = (value) => Number(value).toLocaleString("en-US");
  if (!total) return "0 posts";
  if (painted >= total) return n(total) + (total === 1 ? " post" : " posts");
  return n(painted) + " of " + n(total);
}
function measureStack() {
  const mast = document.querySelector(".mast");
  const bar = document.querySelector(".toolbar");
  if (!mast || !bar) return;
  const h = Math.ceil(mast.getBoundingClientRect().height + bar.getBoundingClientRect().height);
  document.documentElement.style.setProperty("--stack-h", h + "px");
}
let mode = MODE;
let userScrolled = false;
let holdScroll = 0;
let quietLoads = 0;
window.addEventListener("scroll", () => {
  if (holdScroll) return;
  userScrolled = true;
}, { passive: true });
function scrollToY(y) {
  if (window.scrollY === y) return;
  holdScroll += 1;
  window.scrollTo({ top: y, left: 0, behavior: "instant" });
  requestAnimationFrame(() => {
    requestAnimationFrame(() => { holdScroll = Math.max(0, holdScroll - 1); });
  });
}
function paint(resetWindow) {
  const range = activeRange();
  const all = matching();
  const slice = all.slice(0, state.shown);
  const tally = document.getElementById("tally");
  const feed = document.getElementById("feed");
  const more = document.getElementById("more");
  const y = resetWindow ? 0 : window.scrollY;
  const open = resetWindow ? new Set() : new Set(
    [...feed.querySelectorAll("details[open][data-pid]")].map((el) => el.dataset.pid)
  );
  tally.textContent = tallyText(slice.length, all.length);
  if (!slice.length) {
    feed.innerHTML = '<div class="empty"><p>' + emptyMessage(range) + "</p></div>";
    more.hidden = true;
  } else {
    feed.innerHTML = mode === "spine"
      ? renderSpine(slice)
      : (mode === "condensed"
          ? (state.density === "group" ? renderGrouped(slice) : renderCondensed(slice))
          : renderMerged(slice));
    feed.querySelectorAll("details[data-pid]").forEach((el) => {
      if (open.has(el.dataset.pid)) el.open = true;
    });
    if (mode === "spine") bindSpineAccordion(feed);
    more.hidden = slice.length >= all.length;
  }
  if (window.scrollY !== y) scrollToY(y);
}
function fillIfBottomVisible() {
  if (userScrolled || quietLoads > 12) return;
  const more = document.getElementById("more");
  if (!more || more.hidden) return;
  if (more.getBoundingClientRect().top >= window.innerHeight) return;
  quietLoads += 1;
  loadMore();
}
function render(opts) {
  const resetWindow = !!(opts && opts.resetWindow);
  if (resetWindow) {
    state.shown = PAGE;
    quietLoads = 0;
  }
  paint(resetWindow);
  requestAnimationFrame(fillIfBottomVisible);
}
function loadMore() {
  const total = matching().length;
  if (state.shown >= total) return;
  state.shown = Math.min(state.shown + PAGE, total);
  render();
}
function syncClear() {
  document.getElementById("q-clear").hidden = document.getElementById("q").value.length === 0;
}
function syncRangeUI() {
  const custom = state.range === "custom";
  document.getElementById("custom-dates").hidden = !custom;
  const range = activeRange();
  const invalid = rangeInvalid(range);
  const readout = document.getElementById("range-readout");
  readout.hidden = custom || invalid;
  readout.textContent = invalid ? "" : rangeText(range);
  document.getElementById("range-error").hidden = !invalid;
  ["from", "to"].forEach((id) => {
    const el = document.getElementById(id);
    if (invalid && custom) {
      el.setAttribute("aria-invalid", "true");
      el.setAttribute("aria-describedby", "range-error");
    } else {
      el.setAttribute("aria-invalid", "false");
      el.removeAttribute("aria-describedby");
    }
  });
  measureStack();
}
function applyDateBounds() {
  const today = todayET();
  let max = today;
  POSTS.forEach((post) => {
    if (post.day && post.day > max) max = post.day;
  });
  ["from", "to"].forEach((id) => { document.getElementById(id).max = max; });
}
function setMode(next) {
  mode = next;
  document.body.dataset.mode = next;
  document.body.classList.toggle("mode-spine", mode === "spine");
  document.body.classList.toggle("mode-merged", mode === "merged");
  document.body.classList.toggle("mode-condensed", mode === "condensed");
  const viewName = mode === "spine" ? "Timeline" : (mode === "condensed" ? "Condensed Feed" : "Feed");
  document.title = "Commander in Feed — " + viewName;
  document.querySelectorAll("button[data-mode]").forEach((btn) => {
    btn.setAttribute("aria-pressed", btn.dataset.mode === mode ? "true" : "false");
  });
  measureStack();
  render();
}
const q = document.getElementById("q");
q.addEventListener("input", () => {
  state.q = q.value;
  syncClear();
  render({ resetWindow: true });
});
q.addEventListener("keydown", (event) => {
  if (event.key !== "Escape" || !q.value) return;
  event.preventDefault();
  q.value = "";
  state.q = "";
  syncClear();
  render({ resetWindow: true });
});
document.getElementById("q-clear").addEventListener("click", () => {
  q.value = "";
  state.q = "";
  syncClear();
  q.focus();
  render({ resetWindow: true });
});
document.querySelectorAll("button[data-mode]").forEach((btn) => {
  btn.addEventListener("click", () => setMode(btn.dataset.mode));
});
document.querySelectorAll("button[data-density]").forEach((btn) => {
  btn.addEventListener("click", () => {
    state.density = btn.dataset.density;
    document.querySelectorAll("button[data-density]").forEach((other) => {
      other.setAttribute("aria-pressed", other === btn ? "true" : "false");
    });
    if (mode !== "condensed") setMode("condensed");
    else render();
  });
});
document.querySelectorAll("input[data-account]").forEach((box) => {
  box.addEventListener("change", () => {
    if (box.checked) state.hidden.delete(box.dataset.account);
    else state.hidden.add(box.dataset.account);
    render({ resetWindow: true });
  });
});
document.querySelectorAll('input[name="dates"]').forEach((radio) => {
  radio.addEventListener("change", () => {
    if (!radio.checked) return;
    if (radio.value === "custom" && state.range !== "custom") {
      const current = presetRange(Number(state.range) || 14);
      state.customFrom = current.from;
      state.customTo = current.to;
      document.getElementById("from").value = current.from;
      document.getElementById("to").value = current.to;
    }
    state.range = radio.value;
    syncRangeUI();
    render({ resetWindow: true });
  });
});
function readCustom() {
  state.range = "custom";
  document.querySelector('input[name="dates"][value="custom"]').checked = true;
  state.customFrom = document.getElementById("from").value;
  state.customTo = document.getElementById("to").value;
  syncRangeUI();
  render({ resetWindow: true });
}
document.getElementById("from").addEventListener("change", readCustom);
document.getElementById("to").addEventListener("change", readCustom);
const more = document.getElementById("more");
const moreObserver = new IntersectionObserver((entries) => {
  if (!userScrolled) return;
  if (more.hidden) return;
  if (!entries.some((entry) => entry.isIntersecting)) return;
  loadMore();
}, { rootMargin: "480px 0px" });
moreObserver.observe(more);
window.addEventListener("resize", measureStack);
if (window.ResizeObserver) {
  const ro = new ResizeObserver(measureStack);
  ro.observe(document.querySelector(".mast"));
  ro.observe(document.querySelector(".toolbar"));
}
globalThis.CIF_REFRESH = () => render({ resetWindow: true });
applyDateBounds();
const initial = presetRange(14);
state.customFrom = initial.from;
state.customTo = initial.to;
document.getElementById("from").value = initial.from;
document.getElementById("to").value = initial.to;
syncRangeUI();
syncClear();
measureStack();
render();
